SCRIPT = """document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copy);button.textContent='Empreinte copiée';}catch{button.textContent='Sélectionnez et copiez l’empreinte ci-dessus';}}));"""

def shell(title, description, current, body):
    nav = ''.join(f'<a href="{url}"'+(' aria-current="page"' if name==current else '')+f'>{name}</a>' for name,url in [('Accueil','/'),('Studio','/kyronext-studio/'),('Sentinel','/sentinel/'),('Soutenir','/soutenir/')])
    return f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b080e"><title>{title}</title><meta name="description" content="{description}"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:type" content="website"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/site-assets/site.css"><script src="/site-assets/site.js" defer></script></head><body id="top"><a class="skip" href="#main-content">Aller au contenu</a><header class="top"><div class="wrap"><a class="brand" href="/">KITT FRANCO-BELGE<small>KYRONEXT SYSTEM BY MANIX</small></a><nav aria-label="Navigation principale">{nav}</nav></div></header><main id="main-content">{body}</main><footer class="footer"><div class="wrap"><div><strong>KYRONEXT SYSTEM BY MANIX</strong><p>La technologie, avec une âme de Knight Rider.</p></div><div><a href="/documents">Documents</a><a href="/mentions-legales">Mentions légales</a><a href="/privacy">Confidentialité</a><a href="https://kyronext.eu" rel="noopener noreferrer" target="_blank">Kyronext.eu ↗</a></div></div></footer></body></html>'''

