def feature(index,title,text): return f'<article class="card"><span class="index">{index}</span><h3>{title}</h3><p>{text}</p></article>'
def download(title,url,digest,size,steps,arm_url='',arm_size='',arm_digest=''):
    win_info = 'Windows 10 / 11 &middot; 64 bits'
    arm_info = ' + Ubuntu ARM64 &middot; AGX Orin' if arm_url else ''
    arm_link = f'<a class="secondary" href="{arm_url}">T&eacute;l&eacute;charger pour Ubuntu ARM64 (AGX Orin, {arm_size}) &darr;</a>' if arm_url else ''
    arm_hash = f'<div class="hash">SHA-256 Ubuntu ARM64<br>{arm_digest}</div><button class="copy" data-copy="{arm_digest}">Copier l’empreinte ARM64</button>' if arm_digest else ''
    return f'''<section id="telecharger" class="section wrap"><div class="download-box"><div><p class="eyebrow">PR&Ecirc;T POUR VOTRE COCKPIT</p><h2>{title}</h2><p>{win_info}{arm_info}</p><div class="actions"><a class="primary" href="{url}">T&eacute;l&eacute;charger pour Windows &darr;</a>{arm_link}</div><div class="facts"><span>Windows : {size}</span><span>Installation guid&eacute;e</span><span>Voix fran&ccedil;aise locale</span></div><div class="hash">SHA-256 Windows<br>{digest}</div><button class="copy" data-copy="{digest}">Copier l’empreinte Windows</button>{arm_hash}</div><div><h3>Installation</h3><ol class="steps">{''.join('<li>'+step+'</li>' for step in steps)}</ol><p class="fine">Sur Windows, SmartScreen peut signaler que l’installateur n’est pas sign&eacute; num&eacute;riquement. Sur Ubuntu ARM64, installez le paquet .deb pour AGX Orin avec le gestionnaire de logiciels ou apt.</p></div></div></section>'''

