studio_body=f'''<section class="hero"><div class="wrap hero-grid"><div><span class="pill">VERSION 4.5.0 · WINDOWS</span><h1>Votre musique.<br>Votre cockpit.</h1><p>Kyronext Studio réunit lecteur Hi-Fi, bibliothèque musicale et téléchargements MP3 dans une interface dédiée à l’univers KITT.</p><div class="actions"><a class="primary" href="{studio_url}">Télécharger Studio ↓</a><a class="secondary" href="#apercu">Voir l’interface</a></div></div><figure class="hero-shot"><img src="preview-library-4.5.0.png" alt="Bibliothèque musicale Knight Rider de Studio" width="1280" height="800" fetchpriority="high"><figcaption>La bibliothèque, les collections et les commandes Hi-Fi.</figcaption></figure></div></section><div class="wrap"><div class="strip"><span>SON DE DÉMARRAGE COMPLET</span><span>FAVORIS & COLLECTIONS</span><span>FONDU CONFIGURABLE</span></div></div><section class="section wrap"><p class="eyebrow">BIEN PLUS QU’UN LECTEUR</p><h2>Prenez les commandes.</h2><div class="grid">{feature('01 · ÉCOUTER','Une vraie bibliothèque','Organisez vos collections, retrouvez vos favoris et profitez de la lecture continue, du mode aléatoire et de la répétition.')}{feature('02 · ENRICHIR','Vos téléchargements','Ajoutez plusieurs liens, suivez la file et relancez les échecs. La bibliothèque se met à jour après les téléchargements réussis. Utilisez des contenus dont le téléchargement est autorisé.')}{feature('03 · EMPORTER','Votre musique vous suit','Prévisualisez les copies vers une clé USB : espace libre, taille et doublons. Les fichiers existants ne sont pas écrasés.')}</div></section><section id="apercu" class="section wrap"><p class="eyebrow">LA SIGNATURE KNIGHT RIDER</p><h2>Un univers, du premier écran à la lecture.</h2><div class="shots"><figure><img src="preview-library-4.5.0.png" alt="Interface complète de la bibliothèque" loading="lazy"><figcaption>Mode bibliothèque : sélection, recherche et commandes de lecture.</figcaption></figure><figure><img src="preview-installer-4.5.0.png" alt="Installateur décoré KITT et KARR" loading="lazy"><figcaption>Installation décorée, puis prénom personnalisé au premier démarrage.</figcaption></figure></div></section>'''+download('Kyronext Studio 4.5.0',studio_url,studio_hash,'230,5 Mio',['Téléchargez et ouvrez l’installateur.','Choisissez le dossier d’installation.','Indiquez votre prénom au premier lancement.','Ajoutez votre musique et explorez le cockpit.'])+'''<section class="section wrap faq"><h2>Avant de démarrer</h2><details><summary>Le logiciel utilise-t-il mon prénom ?</summary><p>Le premier lancement demande le prénom de la personne qui utilise le logiciel. Les préférences sont propres à son compte utilisateur.</p></details><details><summary>Le téléchargement nécessite-t-il Internet ?</summary><p>Oui. L’écoute de vos fichiers locaux reste disponible sans Internet. Certains contenus en ligne peuvent être indisponibles ou soumis à des restrictions.</p></details><details><summary>Existe-t-il une version Linux ?</summary><p>Des scripts Linux historiques sont conservés ci-dessous. Ils ne constituent pas la version Windows 4.5.0 et n’ont pas été validés dans cette livraison.</p><a href="./Kyronext-Studio-linux-x86_64" download>Script Linux x86_64 ↓</a> · <a href="./Kyronext-Studio-linux-aarch64" download>Script Linux ARM64 ↓</a></details><details><summary>Comment soutenir le projet ?</summary><p>Partagez vos retours et faites découvrir les logiciels. <a href="/soutenir/">Voir la page de soutien.</a></p></details><a class="backtop" href="#top">Retour en haut ↑</a></section>'''

sentinel_body=f'''<section class="hero"><div class="wrap hero-grid"><div><span class="pill">VERSION 1.1.2 · WINDOWS + UBUNTU ARM64</span><h1>Vos Jetson.<br>Sous surveillance.</h1><p>KITT Sentinel vous aide à suivre vos machines : présence Tailscale, accès SSH et état des services, avec des annonces vocales françaises.</p><div class="actions"><a class="primary" href="{sentinel_url}">Télécharger Sentinel ↓</a><a class="secondary" href="#diagnostic">Découvrir le diagnostic</a></div></div><figure class="hero-shot"><img src="diagnostic-1.1.0.png" alt="Diagnostic Sentinel en mode démonstration" width="1280" height="800" fetchpriority="high"><figcaption>Capture de démonstration : ces données ne sont pas des mesures en direct.</figcaption></figure></div></section><div class="wrap"><div class="strip"><span>VOIX GUY FRANÇAISE LOCALE</span><span>DIAGNOSTIC EN LECTURE SEULE</span><span>HISTORIQUE CONSULTABLE</span></div></div><section id="diagnostic" class="section wrap"><p class="eyebrow">COMPRENDRE AVANT D’AGIR</p><h2>Un statut clair, pour chaque machine.</h2><div class="grid">{feature('01 · PRÉSENCE','Connecté, accessible, en santé','La présence Tailscale est distincte des ports ouverts et de la santé des services. Une information manquante reste indisponible, jamais inventée.')}{feature('02 · DIAGNOSTIC','Les bons contrôles','Vérifiez les ports, l’accès SSH, l’heure et les services configurés. Le diagnostic collecte des informations sans modifier les appareils.')}{feature('03 · PERSONNALISER','Votre poste de supervision','Réglez les seuils de santé, la fréquence de contrôle, les informations des appareils et les annonces vocales. Consultez les événements avec les filtres du journal.')}</div><p class="notice">Les températures, la mémoire et les services nécessitent une machine accessible et un accès SSH autorisé. Installer Sentinel ne donne pas automatiquement accès à un Jetson.</p></section>'''+download('KITT Sentinel 1.1.2',sentinel_url,sentinel_hash,'305,1 Mio',['Installez Sentinel sur votre PC Windows ou votre Jetson AGX Orin.','Connectez Tailscale au compte qui voit vos Jetson.','Configurez les accès SSH autorisés si nécessaire.','Lancez le diagnostic et choisissez vos alertes.'],arm_url=sentinel_arm_url,arm_size='336,7 Mio',arm_digest=sentinel_arm_hash)+'''<section class="section wrap faq"><h2>Vos questions</h2><details><summary>Pourquoi aucune température n’apparaît ?</summary><p>La présence Tailscale seule ne fournit pas la température. Il faut aussi un accès SSH fonctionnel et une machine joignable.</p></details><details><summary>Une machine absente est-elle forcément éteinte ?</summary><p>Non. Elle peut avoir perdu le réseau, être déconnectée de Tailscale ou appartenir à un autre compte. Sentinel distingue les informations disponibles.</p></details><details><summary>La voix dépend-elle du cloud ?</summary><p>La voix Guy incluse est synthétisée localement. Les anciens profils vocaux sont conservés.</p></details><details><summary>Peut-on utiliser une adresse locale ?</summary><p>Une adresse locale de secours peut être configurée explicitement. Son accessibilité ne signifie pas que Tailscale est connecté.</p></details><a class="backtop" href="#top">Retour en haut ↑</a></section>'''
support_body='''<section class="wrap support-hero"><p class="eyebrow">LE PROJET GRANDIT AVEC VOUS</p><h1>Une passion.<br>Une communauté.</h1><p>Merci de faire vivre KITT Franco-Belge et Kyronext. Vos idées, vos tests et vos retours participent à chaque amélioration.</p><div class="actions"><a class="primary" href="/#contact">Envoyer un retour ↗</a><a class="secondary" href="/kyronext-studio/">Découvrir les logiciels</a></div></section><section class="wrap"><div class="notice"><strong>Le paiement est en préparation.</strong><br>Aucun don financier n’est actuellement proposé sur cette page.</div><div class="grid">'''+feature('01','Testez & partagez','Vous avez repéré un problème ? Décrivez les étapes et la version utilisée pour nous aider à le reproduire.')+feature('02','Faites découvrir','Partagez le site avec les passionnés de Knight Rider, de musique et de Jetson autour de vous.')+feature('03','Participez','Proposez vos vidéos, consultez les ressources et échangez avec la communauté.')+'''</div><div class="section"></div></section>'''

for base in (ROOT, ROOT/'client/public'):
    assets=base/'site-assets';assets.mkdir(exist_ok=True)
    (assets/'site.css').write_text(STYLE,encoding='utf-8')
    (assets/'site.js').write_text(SCRIPT,encoding='utf-8')
    for folder,title,desc,current,body in [
      ('kyronext-studio','Kyronext Studio 4.5.0 — Le cockpit Hi-Fi Knight Rider','Lecteur Hi-Fi, bibliothèque musicale et téléchargements MP3 sur Windows. Découvrez Kyronext Studio par Manix.','Studio',studio_body),
      ('sentinel','KITT Sentinel 1.1.2 — Votre poste de supervision Jetson','Surveillez vos Jetson avec Tailscale, SSH, diagnostics et voix Guy française locale. Applications Windows et Ubuntu ARM64.','Sentinel',sentinel_body),
      ('soutenir','Soutenir le projet — KITT Franco-Belge','Participez à KITT Franco-Belge et Kyronext : tests, retours et partage avec la communauté.','Soutenir',support_body)]:
        (base/folder/'index.html').write_text(shell(title,desc,current,body),encoding='utf-8')
print('Six public pages generated; versioned download URLs preserved.')
